import java.util.*;
public class EqualityContractDemo {
  public static void main(String[] args) {
    record Key(String id) {}
    var a=new Key("P1"); var b=new Key("P1"); var c=new Key("P1");
    System.out.println(a.equals(a)+" "+a.equals(b)+" "+b.equals(a)+" "+(a.equals(b)&&b.equals(c)&&a.equals(c)));
  }
}
